'use strict';

const fs = require('fs');
const data = fs.readFileSync(0);
let pos = 0;

function nextInt() {
  while (pos < data.length && data[pos] <= 32) pos++;
  let value = 0;
  while (pos < data.length && data[pos] > 32) {
    value = value * 10 + data[pos] - 48;
    pos++;
  }
  return value;
}

const N = nextInt();
const K = nextInt();
const U = nextInt();

const cards = new Uint16Array(N * K);
for (let i = 0; i < cards.length; i++) {
  cards[i] = nextInt();
}

const rank = new Uint32Array(U + 1);
for (let i = 1; i <= U; i++) {
  rank[nextInt()] = i;
}

const completion = new Uint32Array(N);
let earliest = Infinity;

for (let i = 0; i < N; i++) {
  let last = 0;
  const start = i * K;
  for (let j = 0; j < K; j++) {
    const drawRank = rank[cards[start + j]];
    if (drawRank > last) last = drawRank;
  }
  completion[i] = last;
  if (last < earliest) earliest = last;
}

const winners = [];
for (let i = 0; i < N; i++) {
  if (completion[i] === earliest) winners.push(i + 1);
}

process.stdout.write(winners.join(' ') + '\n');
